// Canonical: flatten + two-pointer (single BST, target k)
function findTarget(root, k):
    arr = []
    inorder(root, arr)        // arr is now ascending
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        s = arr[lo] + arr[hi]
        if s == k:   return true
        if s <  k:   lo += 1   // need bigger -> raise low
        else:        hi -= 1   // need smaller -> lower high
    return false

// Two BSTs: inorder(t1) ascending, inorder(t2) descending,
// then identical two-pointer comparing s vs target across arrays.

