prefix = 0
answer = 0
for j in 0 .. n-1:
    prefix += a[j]
    key = normalize(prefix)        // raw value, or residue mod k
    need = complement(key)         // prefix - k, or same residue
    if need in seen:
        answer += seen[need]       // count; or use stored index for length
    // store: increment count, OR keep-earliest for length/index problems
    if key not in seen: seen[key] = j      // earliest-index variant
    else: seen[key] += 1                   // frequency variant
