function primePairs(n):
    if n < 4: return []
    isPrime = array(n+1, true)
    isPrime[0] = isPrime[1] = false
    for p from 2 while p*p <= n:
        if isPrime[p]:
            for m from p*p to n step p:
                isPrime[m] = false
    result = []
    for x from 2 to n/2:          // x <= y guaranteed
        y = n - x
        if isPrime[x] and isPrime[y]:
            result.append([x, y])
    return result                 // already sorted by x

