    return dfs(root, mask = 0)

function dfs(node, mask):
    if node == null: return 0
    mask ^= (1 << node.val)          # toggle parity of this digit
    if node.left == null and node.right == null:   # leaf = end of a path
        return 1 if (mask & (mask - 1)) == 0 else 0  # popcount <= 1
    return dfs(node.left, mask) + dfs(node.right, mask)

