function isPalindrome(s):
    left = 0, right = len(s) - 1
    while left < right:
        # optional: skip irrelevant chars (e.g. #125)
        while left < right and not valid(s[left]):  left++
        while left < right and not valid(s[right]): right--
        if normalize(s[left]) != normalize(s[right]):
            return false            # or branch for one-deletion (#680)
        left++; right--
    return true

