function isKPalindrome(s, k):
    n = len(s)
    # dp[i][j] = min deletions to make s[i..j] a palindrome
    dp = 2D array n x n, init 0
    for i from n-1 down to 0:
        for j from i+1 to n-1:
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i+1][j], dp[i][j-1])
    return dp[0][n-1] <= k
