shortest-path.pseudo:
function ladderLength(begin, end, wordList):
  if end not in wordList: return 0
  patterns = map: "h*t" -> [words]      # precompute buckets
  for w in wordList: for i in 0..L-1: patterns[w[:i]+"*"+w[i+1:]].add(w)
  queue = [(begin, 1)]; visited = {begin}
  while queue not empty:
    (word, dist) = queue.pop_front()
    for i in 0..L-1:
      key = word[:i] + "*" + word[i+1:]
      for nb in patterns[key]:
        if nb == end: return dist + 1
        if nb not in visited:
          visited.add(nb); queue.push_back((nb, dist+1))
      patterns[key] = []               # clear consumed bucket
  return 0

