// canonical: at-most-k transactions over price array (covers all 6)
function maxProfit(k, prices):
    if k >= len(prices)/2:          // cap non-binding -> unlimited case (#122)
        return sum(max(0, prices[i]-prices[i-1]) for i in 1..n-1)
    buy  = [-INF] * (k+1)           // buy[j]: best cash holding share, j-th txn
    sell = [0]    * (k+1)           // sell[j]: best cash after closing j txns
    for p in prices:
        for j in 1..k:
            buy[j]  = max(buy[j],  sell[j-1] - p)   // open j-th position
            sell[j] = max(sell[j], buy[j]    + p)   // close it (subtract fee here if any)
    return sell[k]
// k=1 -> #121/123 with k=2 ; cooldown -> use prev_sell when reopening buy

