    for j in 1..k:
        // buy the j-th share (uses cash[j-1]) or keep holding
        hold[j] = max(hold[j], cash[j-1] - price)
        // sell the j-th share (completes transaction j) or keep cash
        cash[j] = max(cash[j], hold[j] + price)
