def calc(s):                       # Basic Calculator III style
    stack = []; num = 0; op = '+'; i = 0
    while i < len(s):
        c = s[i]
        if c.isdigit(): num = num*10 + int(c)
        if c == '(':                # recurse on the matched substring
            num, i = calc_from(s, i+1)   # returns value + index past ')'
        if c in "+-*/)" or i == len(s)-1:
            if op == '+': stack.append(num)
            elif op == '-': stack.append(-num)
            elif op == '*': stack.append(stack.pop()*num)
            elif op == '/': stack.append(int(stack.pop()/num))
            op = c; num = 0
            if c == ')': break
        i += 1
    return sum(stack)              # precedence resolved by deferred sum

