eval(s):
  nums = []; num = 0; op = '+'        # op = operator preceding current num
  for i, c in enumerate(s + '+'):     # sentinel flushes last term
    if c == '(': num, j = eval(s from i+1); i = j   # recurse on sub-expr
    if c is digit: num = num*10 + int(c)
    if c == ')' or c is operator-or-sentinel and not space:
       if op == '+': nums.push(+num)
       if op == '-': nums.push(-num)
       if op == '*': nums.push(nums.pop() * num)
       if op == '/': nums.push(int(nums.pop() / num))
       op = c; num = 0
       if c == ')': break             # return sum(nums), i
  return sum(nums)

