// #282 incremental backtracking (build + evaluate)
backtrack(start, cur, prev, path):
    if start == len(s):
        if cur == target: emit(path); return
    for end in start..len(s):
        if s[start]=='0' and end>start: break        // leading zero
        d = int(s[start..end])
        if start == 0:                                // first operand, no op
            backtrack(end+1, d, d, str(d))
        else:
            backtrack(end+1, cur+d,  d,      path+"+"+d)
            backtrack(end+1, cur-d, -d,      path+"-"+d)
            backtrack(end+1, cur-prev+prev*d, prev*d, path+"*"+d)  // fix precedence

