function daysToComplete(tasks, space):
    nextAllowed = empty hash map      # task -> earliest day it may run
    day = 0
    for t in tasks:
        day = day + 1                 # consume one day for this task
        if t in nextAllowed:
            day = max(day, nextAllowed[t])
        nextAllowed[t] = day + space + 1   # set cooldown horizon
    return day
